import { query } from '../config/db.js';

export const createBooking = async (req, res) => {
    // 1. Extract data safely from the request
    const { slot_id, student_id, parent_id } = req.body; 

    // Basic Validation
    if (!slot_id || !student_id || !parent_id) {
        return res.status(400).json({ error: "Missing required fields" });
    }

    try {
        // 2. Fetch the teacher_id and date from the inventory (meeting_slots)
        // Notice the $1 parameterized query to prevent SQL Injection
        const slotResult = await query(
            `SELECT teacher_id, date FROM meeting_slots WHERE id = $1 AND status = 'AVAILABLE'`, 
            [slot_id]
        );

        if (slotResult.rows.length === 0) {
            return res.status(404).json({ error: "Slot not found or already booked." });
        }

        const { teacher_id, date } = slotResult.rows[0];

        // 3. Insert the Booking
        // This is where our Database Constraints (UNIQUE slot_id) save us from race conditions!
        const insertResult = await query(
            `INSERT INTO bookings (slot_id, parent_id, student_id, teacher_id, booking_date)
             VALUES ($1, $2, $3, $4, $5) RETURNING id`, 
            [slot_id, parent_id, student_id, teacher_id, date]
        );

        // 4. Update the slot status to 'BOOKED'
        await query(`UPDATE meeting_slots SET status = 'BOOKED' WHERE id = $1`, [slot_id]);

        return res.status(201).json({
            message: "Booking created successfully!",
            booking_id: insertResult.rows[0].id
        });

    } catch (error) {
        // 5. Catch the Race Condition! (Postgres Error Code: 23505 = Unique Violation)
        if (error.code === '23505') {
            return res.status(409).json({
                error: "Double-booking detected! This slot was grabbed by someone else milliseconds before you."
            });
        }

        console.error(error);
        return res.status(500).json({ error: "Internal server error" });
    }
};
```

### The Concepts to talk about in the Interview:
1. **Destructuring & Validation (`const { slot_id } = req.body;`)**: Emphasize that you *always* validate input early to avoid crashing the DB with null values.
2. **Parameterized SQL (`$1`)**: Explicitly point out to the interviewer that you are not using template literals (`${slot_id}`) inside the SQL string to guarantee protection against SQL injection.
3. **The Postgres Error Catch (`if (error.code === '23505')`)**: Explain that because we rely on the `UNIQUE` constraint, we avoid race conditions natively. If two parents hit line 31 at the exact same millisecond, Postgres will throw a `23505` error for the second one, which we gracefully catch and return as a `409 Conflict`.

